class IntBox {
      int* data;
  public:
      IntBox(int val) : data(new int(val)) {}
      // Deep Copy Constructor:
      IntBox(const IntBox& other) : data(new int(*other.data)) {}
      // Deep Copy Assignment (Rule of 3):
      IntBox& operator=(const IntBox& other) {
          if (this == &other) return *this;
          int* fresh = new int(*other.data); // allocate first (exception safe)
          delete data;
          data = fresh;
          return *this;
      }
      ~IntBox() { delete data; }
  };

